import { SignInButton } from "@clerk/nextjs";
import { currentClerkUserId } from "@/lib/auth";
import { getStore } from "@/lib/runtime";
import { hashToken, randomToken } from "@/lib/tokens";
export default async function AuthorizePage({ searchParams }: { searchParams: Promise<{ state?: string; device?: string }> }) { const userId = await currentClerkUserId(); const { state, device } = await searchParams; if (!userId) return <section className="card"><h1>Sign in to Hex Connect</h1><p>Sign in to connect this app to your daemons.</p>{process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ? <SignInButton mode="modal"><button>Sign in</button></SignInButton> : <p className="error">Set DEV_USER_ID for local use, or configure Clerk.</p>}</section>; if (!state || !device || state.length > 256 || device.length > 100) return <section className="card"><h1>Invalid request</h1><p className="error">The authorization link is missing a valid state or device name.</p></section>; const user = await getStore().getOrCreateUser(userId); const token = randomToken("hxc_"); await getStore().createClientSession({ userId: user.id, tokenHash: hashToken(token), deviceName: device }); const href = `hexbot://connect?state=${encodeURIComponent(state)}#session=${encodeURIComponent(token)}`; return <section className="card"><h1>Open Hexbot</h1><p>Continue to send this sign-in back to {device}. The session token stays in the URL fragment.</p><a className="button" href={href}>Open Hexbot</a></section>; }
